INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8701, '1 Kings 15:12', '1 Kings', 15, 12, '&nbsp;هغۀ د مُلک د بُتانو د عبادت د ځايونو نه ټول نران او ښځې کنجرې وويستلې او هغه ټول بُتان يې لرې کړل چې د هغۀ پلار نيکۀ جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8702, '1 Kings 15:13', '1 Kings', 15, 13, '&nbsp;هغۀ خپله نيا معکه د ”مور مَلِکه“ د عُهدې نه لرې کړه، ځکه چې هغې د اشيرې يو بې‌حيا بُت جوړ کړے وو. آسا دا بُت مات کړو او د قِدرون په مېدان کښې يې وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8703, '1 Kings 15:14', '1 Kings', 15, 14, '&nbsp;اګر چې آسا علاقائى عبادتخانې نۀ وې تباه کړى، خو بيا هم ټول عُمر د مالِک خُدائ وفادار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8704, '1 Kings 15:15', '1 Kings', 15, 15, '&nbsp;د هغۀ پلار چې کوم څيزونه خُدائ پاک ته وقف کړى وُو نو هغه ټول يې د مالِک خُدائ په کور کښې کېښودل، د سرو زرو او سپينو زرو هغه څيزونه يې هم کېښودل چې هغۀ په خپله وقف کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8705, '1 Kings 15:16', '1 Kings', 15, 16, '&nbsp;د يهوداه بادشاه آسا او د اِسرائيل بادشاه بعشا د خپلې بادشاهۍ په دوران کښې همېشه د يو بل خِلاف په جنګ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8706, '1 Kings 15:17', '1 Kings', 15, 17, '&nbsp;بعشا په يهوداه حمله وکړه او د راما نه يې پاخۀ دېوالونه تاو کړل چې د يهوداه ټول تګ راتګ بند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8707, '1 Kings 15:18', '1 Kings', 15, 18, '&nbsp;نو آسا بادشاه هغه ټول سپين زر او سرۀ زر يوړل چې د مالِک خُدائ په کور او محل په خزانو کښې پاتې وُو او دا يې د خپلو آفسرانو په ذريعه د دې پېغام سره دمشق ته د شام بادشاه بِن‌حدد له ولېږل چې هغه د حزيون نمسے او طاب‌رمون زوئ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8708, '1 Kings 15:19', '1 Kings', 15, 19, '&nbsp;”راځه چې زمونږ د پلار نيکۀ په شان په خپلو کښې لوظ وکړُو. ګوره، دا سپين زر او سرۀ زر تحفه درلېږم. نو د اِسرائيل بادشاه بعشا سره خپل اِتحاد مات کړه، چې هغه زما د علاقې نه خپل فوجيان بهر کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8709, '1 Kings 15:20', '1 Kings', 15, 20, '&nbsp;بِن‌حدد بادشاه د آسا خبرې ته راضى شو او خپل فوجى آفسران او د هغوئ لښکر يې ولېږلو چې د اِسرائيل په ښارونو حمله وکړى. هغوئ عيون، دان، ابيل‌بيت‌معکه، د ګليل ډنډ ته نزدې علاقه او د نفتالى ټوله علاقه قبضه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8710, '1 Kings 15:21', '1 Kings', 15, 21, '&nbsp;کله چې بعشا بادشاه د دې نه خبر شو، نو هغۀ د راما دېوالونه پخول پرېښودل او تِرضاه ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8711, '1 Kings 15:22', '1 Kings', 15, 22, '&nbsp;بيا آسا بادشاه په ټوله يهوداه کښې هر چا ته دا حُکم وکړو چې د راما نه هغه کاڼى او لرګى يوسى چې بعشا د دې پَخو دېوالونو جوړولو دپاره استعمالول. د دې سامان سره آسا د مصفاه او جبعه ښار مضبوط کړو چې د بنيامين په علاقه کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8712, '1 Kings 15:23', '1 Kings', 15, 23, '&nbsp;نور هر څۀ چې آسا بادشاه کړى وُو، د هغۀ د بهادرۍ کارنامې او کوم ښارونه يې چې جوړ کړى وُو، دا هر څۀ د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى. خو په بوډاتوب کښې ورباندې د پښو بيمارى راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8713, '1 Kings 15:24', '1 Kings', 15, 24, '&nbsp;آسا مړ شو او د داؤد د ښار په شاهى اديره کښې ښخ شو او د هغۀ زوئ يهوسفط د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8714, '1 Kings 15:25', '1 Kings', 15, 25, '&nbsp;د يهوداه بادشاه آسا د بادشاهۍ په دوېم کال کښې، د يربعام بادشاه زوئ ندب د اِسرائيل بادشاه شو او دوه کاله يې بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8715, '1 Kings 15:26', '1 Kings', 15, 26, '&nbsp;لکه څنګه چې د هغۀ پلار د مالِک خُدائ خِلاف ګناه کړې وه نو هغۀ هم وکړه او اِسرائيليان يې د ګناه طرف ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8716, '1 Kings 15:27', '1 Kings', 15, 27, '&nbsp;د يساکار قبيلې د اخياه زوئ بعشا د ندب خِلاف منصوبه جوړه کړه او هغه يې ووژلو، په دې وخت کښې ندب او د هغۀ لښکر د فلستيه په مُلک کښې د جبتون ښار محاصره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8717, '1 Kings 15:28', '1 Kings', 15, 28, '&nbsp;د يهوداه بادشاه آسا د بادشاهۍ په درېم کال داسې وشول. او بعشا د ندب نه پس د اِسرائيل بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8718, '1 Kings 15:29', '1 Kings', 15, 29, '&nbsp;څنګه چې هغه بادشاه شو نو هغۀ د يربعام د خاندان کسان ووژل. هم هغه شان چې څنګه مالِک خُدائ د خپل خِدمت کوونکى د سيلا پېغمبر اخياه په ذريعه فرمائيلى وُو، د يربعام مکمل خاندان ووژلے شو، يو کس هم ژوندے پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8719, '1 Kings 15:30', '1 Kings', 15, 30, '&nbsp;دا ځکه چې يربعام د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک غصه راوپاروله، دا د هغې ګناه په وجه چې هغۀ کړې وه او اِسرائيليان هم د ګناه طرف ته بوتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8720, '1 Kings 15:31', '1 Kings', 15, 31, '&nbsp;نور هر څۀ چې ندب کړى وُو نو هغه د اِسرائيل د بادشاهانو د تاريخ په کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8721, '1 Kings 15:32', '1 Kings', 15, 32, '&nbsp;د يهوداه بادشاه آسا او د اِسرائيل بادشاه بعشا هر وخت د يو بل خِلاف په جنګ کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8722, '1 Kings 15:33', '1 Kings', 15, 33, '&nbsp;د يهوداه بادشاه آسا د بادشاهۍ په درېم کال د اخياه زوئ بعشا د ټول اِسرائيل بادشاه شو او څليريشت کاله يې په تِرضاه کښې بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8723, '1 Kings 15:34', '1 Kings', 15, 34, '&nbsp;لکه څنګه چې مخکښې يربعام بادشاه ګناه کړې وه نو هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه او اِسرائيليان يې د ګناه طرف ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8724, '1 Kings 16:1', '1 Kings', 16, 1, '&nbsp;بيا د مالِک خُدائ کلام د حنانى په زوئ ياهُو پېغمبر نازل شو او د بعشا دپاره يې دا پېغام ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8725, '1 Kings 16:2', '1 Kings', 16, 2, '&nbsp;”ما د خاورو نه اوچت کړې او د اِسرائيليانو مشر مې جوړ کړې. خو د يربعام په شان تا هم ګناه کړې ده او زما خلق دې د ګناه طرف ته بوتلى دى. د هغوئ ګناهونو زما غصه راپارولې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8726, '1 Kings 16:3', '1 Kings', 16, 3, '&nbsp;نو زۀ به تا او ستا خاندان تباه کړم، لکه څنګه چې ما يربعام او د هغۀ خاندان تباه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8727, '1 Kings 16:4', '1 Kings', 16, 4, '&nbsp;ستا د خاندان هر يو کس چې په ښار کښې مړ شى نو سپى به يې وخورى او څوک هم چې په مېدان کښې مړۀ شى نو مارغان به يې وخورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8728, '1 Kings 16:5', '1 Kings', 16, 5, '&nbsp;بعشا چې نور هر څۀ هم کړى دى سره د هغۀ د بهادرۍ ټولو کارنامو هغه د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8729, '1 Kings 16:6', '1 Kings', 16, 6, '&nbsp;بعشا مړ شو او په تِرضاه کښې ښخ شو او د هغۀ زوئ ايله د هغۀ نه پس بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8730, '1 Kings 16:7', '1 Kings', 16, 7, '&nbsp;د مالِک خُدائ پېغام د بعشا او د هغۀ خاندان خِلاف د ياهُو پېغمبر په ذريعه ورکړے شوے وو ځکه چې بعشا د مالِک خُدائ په نظر کښې ګناهونه کړى وُو. هغۀ د خپلو بدو عملونو په وجه د مالِک خُدائ غصه راوپاروله، ځکه چې هغۀ د يربعام مکمل خاندان وژلے وو، نو هغه د يربعام په شان ظالم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8731, '1 Kings 16:8', '1 Kings', 16, 8, '&nbsp;د يهوداه بادشاه آسا د بادشاهۍ په شپږويشتم کال، د بعشا زوئ ايله د اِسرائيل بادشاه شو او دوه کاله يې په تِرضاه باندې بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8732, '1 Kings 16:9', '1 Kings', 16, 9, '&nbsp;د هغۀ يو آفسر زِمرى چې د بادشاه د نيمو جنګى ګاډو مشر وو، د بادشاه خِلاف منصوبه جوړه کړه. او ايله يوه ورځ په تِرضاه کښې د محل مشر ارضه په کور کښې د ميو په نشه کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8733, '1 Kings 16:10', '1 Kings', 16, 10, '&nbsp;زِمرى کور ته ورننوتلو، ايله يې ووژلو او د هغۀ په تخت کښېناستو. د يهوداه بادشاه آسا د بادشاهۍ په اوويشتم کال داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8734, '1 Kings 16:11', '1 Kings', 16, 11, '&nbsp;څنګه چې زمرے د هغۀ په تخت کښېناستو، نو هغۀ د بعشا د خاندان ټول کسان ووژل. د هغۀ ټول نران رشته‌دار او نران دوستان يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8735, '1 Kings 16:12', '1 Kings', 16, 12, '&nbsp;نو چې څنګه مالِک خُدائ د ياهُو پېغمبر په ذريعه د بعشا خِلاف فرمائيلى وُو، زِمرى د بعشا مکمل خاندان ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8736, '1 Kings 16:13', '1 Kings', 16, 13, '&nbsp;د خپلې ګناه او د بنى اِسرائيلو د ګناه طرف ته بوتلو په وجه، بعشا او د هغۀ زوئ ايله د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک غصه راوپاروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8737, '1 Kings 16:14', '1 Kings', 16, 14, '&nbsp;ايله چې نور هر څۀ هم کړى وُو نو هغه د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8738, '1 Kings 16:15', '1 Kings', 16, 15, '&nbsp;د يهوداه بادشاه آسا د بادشاهۍ په اوويشتم کال، زِمرى په تِرضاه کښې اووۀ ورځې په اِسرائيل بادشاهى وکړه. د اِسرائيل فوجيانو په فلستيه کښې د جبتون ښار محاصره کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8739, '1 Kings 16:16', '1 Kings', 16, 16, '&nbsp;او کله چې هغوئ خبر شو چې زِمرى د بادشاه خِلاف منصوبه جوړه کړې ده او بادشاه يې وژلے دے، نو هلته هغوئ ټولو دا اِعلان وکړو چې د هغوئ فوجى مشر عُمرى د اِسرائيل بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8740, '1 Kings 16:17', '1 Kings', 16, 17, '&nbsp;عُمرے او د هغۀ فوجيان د جبتون نه لاړل او تِرضاه يې محاصره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8741, '1 Kings 16:18', '1 Kings', 16, 18, '&nbsp;کله چې زِمرى وليدل چې ښار قبضه شوے دے، نو هغه د محل دنننۍ قلعې ته لاړو، په محل يې اور بل کړو او هغه د اور په لمبو کښې مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8742, '1 Kings 16:19', '1 Kings', 16, 19, '&nbsp;د مالِک خُدائ خِلاف د هغۀ د ګناهونو په وجه داسې وشول، لکه څنګه چې د هغۀ نه مخکښېنى يربعام د خپلې ګناه په وجه مالِک خُدائ نارضا کړے وو او اِسرائيليان يې د ګناه طرف ته بوتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8743, '1 Kings 16:20', '1 Kings', 16, 20, '&nbsp;زِمرى چې نور څۀ هم کړى وُو، سره د هغۀ د بغاوت د منصوبې جوړولو، دا د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8744, '1 Kings 16:21', '1 Kings', 16, 21, '&nbsp;نو د دې نه پس اِسرائيليان په دوو ډلو کښې تقسيم شول، نيمو کسانو وئيل چې د جينت زوئ تِبنى بادشاه جوړوُو او نيم د عُمرى په حق کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8745, '1 Kings 16:22', '1 Kings', 16, 22, '&nbsp;خو د عُمرى قبيلې وګټله او د جينت زوئ تِبنى په ډله باندې بريالى شول. تِبنى ووژلے شو او عُمرى بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8746, '1 Kings 16:23', '1 Kings', 16, 23, '&nbsp;نو د يهوداه د آسا بادشاه د بادشاهۍ په يو دېرشم کال، عُمرى د اِسرائيل بادشاه شو او دولس کاله يې بادشاهى وکړه، وړومبے شپږ کاله هغۀ په تِرضاه کښې بادشاهى وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8747, '1 Kings 16:24', '1 Kings', 16, 24, '&nbsp;او بيا هغۀ د سپينو زرو په شپږ زره سيکو باندې د سامريه غر د يو سړى نه واخستلو چې نوم يې سمر وو. عُمرى د غرۀ نه پاخۀ دېوالونه تاو کړل، هلته يې يو ښار جوړ کړو او سامريه نوم يې پرې کېښودو، سمر د دې غر مخکښېنے مالِک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8748, '1 Kings 16:25', '1 Kings', 16, 25, '&nbsp;عُمرى د مالِک خُدائ په نظر کښې بد کارونه کول او د مالِک خُدائ خِلاف يې د مخکښېنو بادشاهانو نه زياته ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8749, '1 Kings 16:26', '1 Kings', 16, 26, '&nbsp;د يربعام په شان، هغۀ هم د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک غصه راوپاروله، دا د هغۀ د خپلې ګناه او د هغه ګناه په وجه وُو چې بنى اِسرائيليان يې د بُت پرستۍ طرف ته بوتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8750, '1 Kings 16:27', '1 Kings', 16, 27, '&nbsp;نور هر څۀ چې عُمرى کړى وُو او د هغۀ ټولې کاميابۍ د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8751, '1 Kings 16:28', '1 Kings', 16, 28, '&nbsp;عُمرى مړ شو او په سامريه کښې ښخ شو او د هغۀ زوئ اخى‌اب د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8752, '1 Kings 16:29', '1 Kings', 16, 29, '&nbsp;د يهوداه بادشاه آسا د بادشاهۍ په اتۀ دېرشم کال، د عُمرى زوئ اخى‌اب د اِسرائيل بادشاه شو، هغۀ په سامريه کښې دوويشت کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8753, '1 Kings 16:30', '1 Kings', 16, 30, '&nbsp;هغۀ د مخکښېنو بادشاهانو د هر يو نه زيات د مالِک خُدائ خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8754, '1 Kings 16:31', '1 Kings', 16, 31, '&nbsp;هغۀ نۀ صرف د يربعام بادشاه ګناهونه معمولى ګڼل بلکې هغۀ د صيدانى بادشاه اِتبعل لور ايزبل هم وادۀ کړه او د بعل عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8755, '1 Kings 16:32', '1 Kings', 16, 32, '&nbsp;هغۀ په سامريه کښې د بعل دپاره يوه عبادتخانه او يوه قربان‌ګاه جوړه کړه او هغه يې په کښې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8756, '1 Kings 16:33', '1 Kings', 16, 33, '&nbsp;هغۀ د اشيرې بُت ولګولو. د اِسرائيل د ټولو مخکښېنو بادشاهانو نه يې زيات د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک غصه راوپاروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8757, '1 Kings 16:34', '1 Kings', 16, 34, '&nbsp;د هغۀ د بادشاهۍ په دوران کښې د بيت‌ايل، حى‌اېل د يريحو ښار بيا جوړ کړو. کله چې حى‌اېل د يريحو بنياد کېښودو نو د هغۀ مشر زوئ ابيرام مړ شو او چې کله يې دروازې جوړې کړې نو د هغۀ کشر زوئ سجوب مړ شو، هم هغه شان لکه چې مالِک خُدائ د نون زوئ يشوَع په ذريعه د دې پېشګوئې کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8758, '1 Kings 17:1', '1 Kings', 17, 1, '&nbsp;په جِلعاد کښې د تِشبى يو پېغمبر وو چې نوم يې الياس وو. هغۀ اخى‌اب بادشاه ته وفرمائيل، ”زۀ د ژوندى مالِک خُدائ يعنې د بنى اِسرائيلو د خُدائ پاک خِدمت کوونکے يم، او زۀ د هغۀ په نوم قسم خورم چې ترڅو زۀ ونۀ وايم نو په راتلونکو کالونو کښې به باران نۀ کيږى. او پرخه قدرې به هم ونۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8759, '1 Kings 17:2', '1 Kings', 17, 2, '&nbsp;بيا د مالِک خُدائ کلام په الياس نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8760, '1 Kings 17:3', '1 Kings', 17, 3, '&nbsp;”د دې ځائ نه نمرخاتۀ طرف ته لاړ شه او د اُردن سيند نمرخاتۀ طرف ته د کريت ولې سره نزدې پټ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8761, '1 Kings 17:4', '1 Kings', 17, 4, '&nbsp;تۀ د ولې نه اوبۀ څښه او ما کارغانو له حُکم ورکړے دے چې هلته تا له خوراک راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8762, '1 Kings 17:5', '1 Kings', 17, 5, '&nbsp;الياس د مالِک خُدائ فرمانبردارى وکړه او د کريت ولې سره نزدې د اوسېدو دپاره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8763, '1 Kings 17:6', '1 Kings', 17, 6, '&nbsp;کارغانو به هغۀ له سحر او ماښام روټۍ او غوښه راوړه او هغۀ د ولې نه اوبۀ څښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8764, '1 Kings 17:7', '1 Kings', 17, 7, '&nbsp;خو څۀ موده وروستو، په مُلک کښې د اوچ کالۍ په وجه هغه وَله اوچه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8765, '1 Kings 17:8', '1 Kings', 17, 8, '&nbsp;بيا د مالِک خُدائ کلام په الياس نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8766, '1 Kings 17:9', '1 Kings', 17, 9, '&nbsp;”اوس د صيدا سره نزدې د صارفت ښار ته لاړ شه او هلته دېره شه. ما هلته يوې کونډې ته وئيلى دى چې تا له خوراک درکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8767, '1 Kings 17:10', '1 Kings', 17, 10, '&nbsp;نو الياس صارفت ته لاړو او چې څنګه هغه د ښار دروازې ته ورسېدو نو هغۀ يوه کونډه وليده چې د اور خشاک يې راغونډولو. نو هغه يې راوغوښته او ورته يې وفرمائيل، ”ما له په جام کښې لږې اوبۀ راوړه چې وې څښم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8768, '1 Kings 17:11', '1 Kings', 17, 11, '&nbsp;څنګه چې هغه اوبو راوړلو له روانه شوه، نو هغۀ آواز ورکړو، ”ما له لږه روټۍ هم راوړه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8769, '1 Kings 17:12', '1 Kings', 17, 12, '&nbsp;کونډې ورته ووئيل، ”زۀ د ژوندى مالِک خُدائ ستا د خُدائ پاک په نوم قسم خورم چې هيڅ مې نۀ دى پاخۀ کړى. ما سره په منګى کښې صِرف يو موټے اوړۀ او په لوښى کښې يو څاڅکے قدرې د زيتُونو تېل دى. زۀ دلته لږ شان خشاک راټولولو له راغلې يم چې ځان سره يې کور ته يوسم او خپل زوئ او ځان له لږ خوراک تيار کړم. او د دې خوراک نه پس به مونږ د لوږې نه مړۀ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8770, '1 Kings 17:13', '1 Kings', 17, 13, '&nbsp;الياس ورته وفرمائيل، ”مۀ يرېږه. کور ته لاړه شه او چې څۀ دې ووئيل نو هم هغه شان وکړه. خو اول، چې تا سره څۀ دى د هغې نه يوه وړه روټۍ پخه کړه او ما له يې لږه راوړه او بيا د خپل زوئ او ځان دپاره څۀ تيار کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8771, '1 Kings 17:14', '1 Kings', 17, 14, '&nbsp;ځکه چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې تر هغې به ستا په منګى کښې اوړۀ او په لوښى کښې تېل ختم نۀ شى ترڅو چې ما مالِک خُدائ په زمکه باران نۀ وى ورولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8772, '1 Kings 17:15', '1 Kings', 17, 15, '&nbsp;هغه کونډه کور ته لاړه او هم هغه شان يې وکړل چې څۀ ورته الياس فرمائيلى وُو. او د هغوئ درېو واړو دپاره د ډېر وخت خوراک موجود وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8773, '1 Kings 17:16', '1 Kings', 17, 16, '&nbsp;مالِک خُدائ هغه وعده پوره کړه چې کومه يې د الياس پېغمبر په ذريعه کړې وه او په منګى کښې نۀ اوړۀ او نۀ په لوښى کښې تېل ختم شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8774, '1 Kings 17:17', '1 Kings', 17, 17, '&nbsp;څۀ موده وروستو، د هغه کونډې ښځې زوئ بيمار شو او ورځ په ورځ هغه نور هم خرابېدو او په آخر کښې يې ساه ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8775, '1 Kings 17:18', '1 Kings', 17, 18, '&nbsp;هغه ښځې الياس ته ووئيل، ”د خُدائ پاک پېغمبره دا تا ما سره څۀ کړى دى؟ تۀ دلته د دې دپاره راغلے يې چې خُدائ پاک ته زما ګناهونه راياد کړې او زما د زوئ د مرګ سبب وګرځې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8776, '1 Kings 17:19', '1 Kings', 17, 19, '&nbsp;الياس ورته وفرمائيل، ”ما له ستا زوئ راکړه.“ بيا هغۀ هلک د هغې د غېږې نه واخستلو او بره يې هغه کوټې ته وخېژولو چرته چې اوسېدو. الياس هغه هلک په خپل کټ کښې واچولو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8777, '1 Kings 17:20', '1 Kings', 17, 20, '&nbsp;او مالِک خُدائ ته يې سوال وکړو، ”اے مالِکه، زما خُدايه پاکه، تا د دې کونډې سره دومره بد ولې وکړل؟ هغه زما سره دومره ښۀ ده چې زما خيال ساتى او اوس تۀ د هغې زوئ وژنې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8778, '1 Kings 17:21', '1 Kings', 17, 21, '&nbsp;بيا الياس درې ځل هغه هلک راغاړه ويستلو او مالِک خُدائ ته يې سوال وکړو، ”اے مالِکه، زما خُدايه پاکه، دا ماشوم دې بيا راژوندے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8779, '1 Kings 17:22', '1 Kings', 17, 22, '&nbsp;مالِک خُدائ د الياس سوال واورېدو او هلک بيا ساه اخستل شروع کړل او ژوندے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8780, '1 Kings 17:23', '1 Kings', 17, 23, '&nbsp;الياس هغه هلک واپس لاندې د هغۀ مور له راوستو او هغې ته يې وفرمائيل، ”وګوره، ستا زوئ ژوندے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8781, '1 Kings 17:24', '1 Kings', 17, 24, '&nbsp;هغه ښځې ورته ووئيل، ”اوس ما ته پته ولګېده چې تۀ د خُدائ پاک پېغمبر يې او ستا د خولې په ذريعه د مالِک خُدائ کلام رښتيا دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8782, '1 Kings 18:1', '1 Kings', 18, 1, '&nbsp;نو څۀ موده وروستو، د اوچ کالۍ په درېم کال، د مالِک خُدائ کلام په الياس نازل شو چې، ”لاړ شه او د اخى‌اب بادشاه په مخکښې حاضر شه، نو زۀ به په زمکه باران راولېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
