(8784, '1 Kings 18:3', '1 Kings', 18, 3, '&nbsp;نو اخى‌اب بادشاه عبدياه راوغوښتو چې هغه يې د محل مشر وو. او عبدياه د مالِک خُدائ ښۀ تابعدار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8785, '1 Kings 18:4', '1 Kings', 18, 4, '&nbsp;او کله چې ايزبل د مالِک خُدائ پېغمبران وژل، نو عبدياه ترې نه سل پېغمبران بوتلل او د پنځوسو پنځوسو په دوو ډلو کښې يې په غارونو کښې پټ کړل او د هغوئ دپاره يې د خوراک او د اوبو بندوبست وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8786, '1 Kings 18:5', '1 Kings', 18, 5, '&nbsp;اخى‌اب عبدياه ته ووئيل، ”راځه چې په ټول مُلک کښې وګرځو او چينې او وادۍ وګورو، کېدے شى چې څۀ واښۀ پېدا شى او قچرې او آسونه پرې ژوندى وساتلے شُو نو زمونږ ټول ځناور به نۀ مړۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8787, '1 Kings 18:6', '1 Kings', 18, 6, '&nbsp;نو زۀ به دېخوا لاړ شم او تۀ اخوا لاړ شه.“ او هغوئ دواړه په بېلو بېلو طرفونو روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8788, '1 Kings 18:7', '1 Kings', 18, 7, '&nbsp;کله چې عبدياه په لاره روان وو، نو ناڅاپه هغه د الياس سره مِلاو شو. هغه يې وپېژندو، د هغۀ په مخکښې ټيټ شو او تپوس يې ترې نه وکړو، ”زما نېکه الياسه. دا په رښتيا تۀ يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8789, '1 Kings 18:8', '1 Kings', 18, 8, '&nbsp;هغۀ ورته وفرمائيل، ”آو، زۀ يم، لاړ شه او خپل نېک يعنې بادشاه ته ووايه چې الياس دلته دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8790, '1 Kings 18:9', '1 Kings', 18, 9, '&nbsp;عبدياه ورته ووئيل، ”ما څۀ بد کړى دى چې تۀ مې اخى‌اب بادشاه ته حواله کوې چې هغه مې ووژنى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8791, '1 Kings 18:10', '1 Kings', 18, 10, '&nbsp;زۀ د ژوندى مالِک خُدائ، ستا د خُدائ پاک په نوم قسم خورم چې بادشاه په تا پسې د دُنيا ټول مُلکونه لټولى دى. کله هم چې د يو مُلک بادشاه ووئيل چې الياس زما په مُلک کښې نشته، نو اخى‌اب به هغه بادشاه ته وئيل چې قسم وخورى چې الياس دلته نشته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8792, '1 Kings 18:11', '1 Kings', 18, 11, '&nbsp;او اوس تۀ ما ته وائې چې لاړ شم او خپل نېک ته ووايم چې الياس دلته دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8793, '1 Kings 18:12', '1 Kings', 18, 12, '&nbsp;خو چې څنګه زۀ لاړ شم نو د مالِک خُدائ روح به تا يو نامعلوم ځائ ته يوسى. بيا چې زۀ اخى‌اب ته ووايم چې تۀ دلته يې او هغه تا پېدا نۀ کړى، نو هغه به ما ووژنى، باوجود د دې چې زۀ د هلکوالى راسې د مالِک خُدائ خِدمت کوونکے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8794, '1 Kings 18:13', '1 Kings', 18, 13, '&nbsp;زما نېکه، تا ته پته نشته څۀ چې کله ايزبل د مالِک خُدائ پېغمبران وژل نو ما د هغوئ سل پېغمبران په دوو غارونو کښې پنځوس پنځوس پټ کړل او د خوراک او د اوبو بندوبست مې ورله وکړو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8795, '1 Kings 18:14', '1 Kings', 18, 14, '&nbsp;نو تۀ ما له څنګه حُکم راکوې چې لاړ شم او بادشاه ته ووايم چې تۀ دلته يې؟ هغه به ما ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8796, '1 Kings 18:15', '1 Kings', 18, 15, '&nbsp;الياس ورته وفرمائيل، ”زۀ د ژوندى ربُ الافواج په نوم لوظ کوم د کوم چې زۀ خِدمت کوم چې زۀ به خپل ځان نن بادشاه ته پېش کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8797, '1 Kings 18:16', '1 Kings', 18, 16, '&nbsp;نو عبدياه اخى‌اب بادشاه له لاړو او ورته يې ووئيل چې الياس راغلے دے. نو اخى‌اب د الياس سره مِلاوېدو له روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8798, '1 Kings 18:17', '1 Kings', 18, 17, '&nbsp;کله چې اخى‌اب هغه وليدو، نو اخى‌اب ورته ووئيل، ”د اِسرائيل د مُلک شريره، دا په رښتيا تۀ يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8799, '1 Kings 18:18', '1 Kings', 18, 18, '&nbsp;الياس ورته وفرمائيل، ”زۀ شرير نۀ يم، بلکې تۀ او ستا د پلار خاندان شرير دے. تۀ د مالِک خُدائ د حُکمونو نافرمانى کوې او د بعل د بُتانو عبادت کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8800, '1 Kings 18:19', '1 Kings', 18, 19, '&nbsp;اوس ټول اِسرائيل له حُکم ورکړه چې د کرمل په غر ما سره مِلاو شى. هغه څلور نيم سوه د بعل پېغمبران او څلور سوه د اشيرې بُت پېغمبران هم ورسره راوله چا چې د مَلِکه ايزبل نه خوراکونه کول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');